def semver_sort(versions):
    def parse_version(version):
        # Split build metadata
        if '+' in version:
            version_part, build = version.split('+', 1)
        else:
            version_part = version
            build = ""

        # Split pre-release
        if '-' in version_part:
            base_part, prerelease = version_part.split('-', 1)
        else:
            base_part = version_part
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = base_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease is not None:
            prerelease_ids = prerelease.split('.')
            # Convert to tuples for comparison
            parsed_ids = []
            for identifier in prerelease_ids:
                if identifier.isdigit():
                    parsed_ids.append((0, int(identifier)))
                else:
                    parsed_ids.append((1, identifier))
            prerelease_tuple = tuple(parsed_ids)
        else:
            prerelease_tuple = None

        return (major, minor, patch, prerelease_tuple)

    def sort_key(item):
        index, version = item
        parsed = parse_version(version)
        major, minor, patch, prerelease = parsed

        # For sorting:
        # - Compare major, minor, patch numerically
        # - Version with prerelease sorts before without prerelease
        #   (achieved by making prerelease=None sort after prerelease=something)
        # - Pre-release identifiers are compared by their parsed tuples
        # - Build metadata is ignored
        # - Equal precedence versions keep input order (using index)

        if prerelease is None:
            # No pre-release: sorts after pre-release versions
            return (major, minor, patch, (1,), index)
        else:
            # Has pre-release: sorts before non-prerelease
            return (major, minor, patch, (0,) + prerelease, index)

    indexed = list(enumerate(versions))
    sorted_versions = sorted(indexed, key=sort_key)
    return [version for _, version in sorted_versions]

